  1→//! Gap checker for requirement evaluation.
  2→//!
  3→//! The `GapChecker` evaluates whether system-level requirements are met,
  4→//! caching results within a run to avoid redundant command executions.
  5→
  6→use crate::requirements::probe::EnvironmentProbe;
  7→use crate::requirements::registry::{
  8→    InstallContext, Platform, RequirementCheck, RequirementRegistry,
  9→};
 10→use crate::requirements::status::{GapResult, RequirementStatus};
 11→use crate::steps::resolved::ResolvedStep;
 12→use std::collections::{HashMap, HashSet};
 13→use std::net::TcpStream;
 14→use std::path::{Path, PathBuf};
 15→use std::process::Command;
 16→use std::time::Duration;
 17→
 18→/// Checks whether requirements are satisfied on the system.
 19→///
 20→/// Caches results per-run so the same requirement checked multiple times
 21→/// only executes commands once.
 22→pub struct GapChecker<'a> {
 23→    registry: &'a RequirementRegistry,
 24→    probe: &'a EnvironmentProbe,
 25→    project_root: PathBuf,
 26→    pub(crate) cache: HashMap<String, RequirementStatus>,
 27→}
 28→
 29→impl<'a> GapChecker<'a> {
 30→    /// Create a new gap checker.
 31→    pub fn new(
 32→        registry: &'a RequirementRegistry,
 33→        probe: &'a EnvironmentProbe,
 34→        project_root: &Path,
 35→    ) -> Self {
 36→        Self {
 37→            registry,
 38→            probe,
 39→            project_root: project_root.to_path_buf(),
 40→            cache: HashMap::new(),
 41→        }
 42→    }
 43→
 44→    /// Check all requirements for a step, returning only non-satisfied gaps.
 45→    ///
 46→    /// `provided_requirements` is authoritative — if the environment says
 47→    /// a requirement is provided, skip the check regardless of what the
 48→    /// step's requires list says. Until environments exist, callers pass `None`.
 49→    pub fn check_step(
 50→        &mut self,
 51→        step: &ResolvedStep,
 52→        provided: Option<&HashSet<String>>,
 53→    ) -> Vec<GapResult> {
 54→        let mut gaps = Vec::new();
 55→        for req_name in &step.requires {
 56→            if let Some(provided_set) = provided {
 57→                if provided_set.contains(req_name) {
 58→                    continue;
 59→                }
 60→            }
 61→
 62→            let status = self.check_one(req_name);
 63→            if !status.is_satisfied() {
 64→                gaps.push(GapResult {
 65→                    requirement: req_name.clone(),
 66→                    status,
 67→                });
 68→            }
 69→        }
 70→        gaps
 71→    }
 72→
 73→    /// Check a single requirement, using cache when available.
 74→    pub fn check_one(&mut self, requirement: &str) -> RequirementStatus {
 75→        if let Some(cached) = self.cache.get(requirement) {
 76→            return cached.clone();
 77→        }
 78→
 79→        let status = self.evaluate(requirement);
 80→        self.cache.insert(requirement.to_string(), status.clone());
 81→        status
 82→    }
 83→
 84→    /// Invalidate a cached result for a specific requirement.
 85→    pub fn invalidate(&mut self, requirement: &str) {
 86→        self.cache.remove(requirement);
 87→    }
 88→
 89→    /// Invalidate all cached results.
 90→    pub fn invalidate_all(&mut self) {
 91→        self.cache.clear();
 92→    }
 93→
 94→    /// Resolve the install dependency chain for a requirement.
 95→    ///
 96→    /// Returns the ordered list of requirements that need to be installed,
 97→    /// with dependencies before dependents. Max depth 5, detects circular deps.
 98→    pub fn resolve_install_deps(&self, requirement: &str) -> Result<Vec<String>, String> {
 99→        let mut chain = Vec::new();
100→        let mut visited = HashSet::new();
101→        self.resolve_deps_recursive(requirement, &mut chain, &mut visited, 0)?;
102→        Ok(chain)
103→    }
104→
105→    fn resolve_deps_recursive(
106→        &self,
107→        requirement: &str,
108→        chain: &mut Vec<String>,
109→        visited: &mut HashSet<String>,
110→        depth: usize,
111→    ) -> Result<(), String> {
112→        const MAX_DEPTH: usize = 5;
113→
114→        if depth > MAX_DEPTH {
115→            return Err(format!(
116→                "Requirement dependency chain exceeds max depth of {} for '{}'",
117→                MAX_DEPTH, requirement
118→            ));
119→        }
120→
121→        if visited.contains(requirement) {
122→            return Err(format!(
123→                "Circular dependency detected: '{}' appears twice in the chain",
124→                requirement
125→            ));
126→        }
127→
128→        let Some(req) = self.registry.get(requirement) else {
129→            // Unknown requirement — add it to chain, let caller handle
130→            if !chain.contains(&requirement.to_string()) {
131→                chain.push(requirement.to_string());
132→            }
133→            return Ok(());
134→        };
135→
136→        visited.insert(requirement.to_string());
137→
138→        // Resolve static dependencies
139→        for dep in &req.depends_on {
140→            self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
141→        }
142→
143→        // Resolve dynamic dependencies
144→        if let Some(install_requires_fn) = req.install_requires {
145→            let ctx = self.build_install_context();
146→            let dynamic_deps = install_requires_fn(&ctx);
147→            for dep in &dynamic_deps {
148→                if !visited.contains(dep) {
149→                    self.resolve_deps_recursive(dep, chain, visited, depth + 1)?;
150→                }
151→            }
152→        }
153→
154→        // Add this requirement after its dependencies
155→        if !chain.contains(&requirement.to_string()) {
156→            chain.push(requirement.to_string());
157→        }
158→
159→        visited.remove(requirement);
160→        Ok(())
161→    }
162→
163→    fn build_install_context(&self) -> InstallContext {
164→        let detected_managers = self
165→            .probe
166→            .inactive_managers()
167→            .iter()
168→            .map(|m| m.name.clone())
169→            .collect::<Vec<_>>();
170→        InstallContext {
171→            detected_managers,
172→            platform: Platform::current(),
173→        }
174→    }
175→
176→    /// Check whether the network is reachable.
177→    ///
178→    /// Attempts a TCP connection to a well-known host with a 2-second timeout.
179→    /// Returns `true` if the connection succeeds, `false` otherwise.
180→    pub fn check_network(&self) -> bool {
181→        // Try multiple well-known hosts to reduce false negatives
182→        const TARGETS: &[(&str, u16)] = &[
183→            ("1.1.1.1", 443), // Cloudflare DNS
184→            ("8.8.8.8", 443), // Google DNS
185→            ("9.9.9.9", 443), // Quad9 DNS
186→        ];
187→        let timeout = Duration::from_secs(2);
188→
189→        for &(host, port) in TARGETS {
190→            let addr = format!("{}:{}", host, port);
191→            if let Ok(addr) = addr.parse() {
192→                if TcpStream::connect_timeout(&addr, timeout).is_ok() {
193→                    return true;
194→                }
195→            }
196→        }
197→        false
198→    }
199→
200→    fn evaluate(&self, requirement: &str) -> RequirementStatus {

  1→//! Git template fetching.
  2→//!
  3→//! Provides functionality for cloning and updating git repositories
  4→//! to fetch templates, with support for specific refs and update detection.
  5→
  6→use anyhow::{bail, Result};
  7→use sha2::{Digest, Sha256};
  8→use std::path::{Path, PathBuf};
  9→
 10→/// Fetches templates from git repositories.
 11→pub struct GitFetcher {
 12→    /// Directory for cloned repositories.
 13→    clone_dir: PathBuf,
 14→}
 15→
 16→/// Information about a git fetch.
 17→#[derive(Debug)]
 18→pub struct GitFetchResult {
 19→    /// Path to the fetched content.
 20→    pub local_path: PathBuf,
 21→    /// Current commit SHA.
 22→    pub commit_sha: String,
 23→}
 24→
 25→impl GitFetcher {
 26→    /// Create a new git fetcher.
 27→    pub fn new(clone_dir: impl Into<PathBuf>) -> Self {
 28→        Self {
 29→            clone_dir: clone_dir.into(),
 30→        }
 31→    }
 32→
 33→    /// Get the clone directory.
 34→    pub fn clone_dir(&self) -> &PathBuf {
 35→        &self.clone_dir
 36→    }
 37→
 38→    /// Clone or update a repository.
 39→    pub fn fetch(&self, url: &str, git_ref: Option<&str>) -> Result<GitFetchResult> {
 40→        let repo_path = self.repo_path(url);
 41→
 42→        if repo_path.exists() {
 43→            self.update_repo(&repo_path, git_ref)?;
 44→        } else {
 45→            self.clone_repo(url, &repo_path, git_ref)?;
 46→        }
 47→
 48→        let commit_sha = self.get_head_sha(&repo_path)?;
 49→
 50→        Ok(GitFetchResult {
 51→            local_path: repo_path,
 52→            commit_sha,
 53→        })
 54→    }
 55→
 56→    /// Check if a repository has new commits.
 57→    pub fn has_updates(&self, url: &str, git_ref: Option<&str>, current_sha: &str) -> Result<bool> {
 58→        let remote_sha = self.resolve_ref(url, git_ref)?;
 59→        Ok(remote_sha != current_sha)
 60→    }
 61→
 62→    /// Get the current commit SHA for a ref using ls-remote.
 63→    pub fn resolve_ref(&self, url: &str, git_ref: Option<&str>) -> Result<String> {
 64→        let refspec = git_ref.unwrap_or("HEAD");
 65→
 66→        // Try the refspec directly, then with refs/heads/ and refs/tags/ prefixes.
 67→        // Short refspecs like "v1.0" may not match "refs/tags/v1.0" in all git versions.
 68→        let candidates = if refspec == "HEAD" {
 69→            vec![refspec.to_string()]
 70→        } else {
 71→            vec![
 72→                refspec.to_string(),
 73→                format!("refs/heads/{refspec}"),
 74→                format!("refs/tags/{refspec}"),
 75→            ]
 76→        };
 77→
 78→        for candidate in &candidates {
 79→            let output = std::process::Command::new("git")
 80→                .args(["ls-remote", url, candidate])
 81→                .output()?;
 82→
 83→            if !output.status.success() {
 84→                bail!(
 85→                    "Failed to query remote: {}",
 86→                    String::from_utf8_lossy(&output.stderr)
 87→                );
 88→            }
 89→
 90→            let stdout = String::from_utf8_lossy(&output.stdout);
 91→            if let Some(sha) = stdout
 92→                .lines()
 93→                .next()
 94→                .and_then(|line| line.split_whitespace().next())
 95→            {
 96→                return Ok(sha.to_string());
 97→            }
 98→        }
 99→
100→        bail!("Could not resolve ref '{refspec}' from {url}")
101→    }
102→
103→    fn clone_repo(&self, url: &str, path: &Path, git_ref: Option<&str>) -> Result<()> {
104→        if let Some(parent) = path.parent() {
105→            std::fs::create_dir_all(parent)?;
106→        }
107→
108→        let mut cmd = std::process::Command::new("git");
109→        cmd.args(["clone", "--depth", "1"]);
110→
111→        if let Some(r) = git_ref {
112→            cmd.args(["--branch", r]);
113→        }
114→
115→        cmd.args([url, &path.to_string_lossy()]);
116→
117→        let output = cmd.output()?;
118→        if !output.status.success() {
119→            bail!(
120→                "Git clone failed: {}",
121→                String::from_utf8_lossy(&output.stderr)
122→            );
123→        }
124→
125→        Ok(())
126→    }
127→
128→    fn update_repo(&self, path: &PathBuf, git_ref: Option<&str>) -> Result<()> {
129→        let output = std::process::Command::new("git")
130→            .args(["fetch", "origin"])
131→            .current_dir(path)
132→            .output()?;
133→
134→        if !output.status.success() {
135→            bail!(
136→                "Git fetch failed: {}",
137→                String::from_utf8_lossy(&output.stderr)
138→            );
139→        }
140→
141→        let refspec = if let Some(r) = git_ref {
142→            format!("origin/{}", r)
143→        } else {
144→            "origin/HEAD".to_string()
145→        };
146→
147→        let output = std::process::Command::new("git")
148→            .args(["reset", "--hard", &refspec])
149→            .current_dir(path)
150→            .output()?;

  1→//! HTTP template fetching.
  2→//!
  3→//! Provides an HTTP client for fetching templates from URLs with
  4→//! support for ETag-based conditional requests.
  5→
  6→use anyhow::{bail, Result};
  7→use reqwest::blocking::Client;
  8→use std::time::Duration;
  9→
 10→/// Default maximum response body size (10 MB).
 11→const DEFAULT_MAX_RESPONSE_SIZE: u64 = 10 * 1024 * 1024;
 12→
 13→/// Fetches templates over HTTP/HTTPS.
 14→pub struct HttpFetcher {
 15→    client: Client,
 16→    timeout: Duration,
 17→    max_response_size: u64,
 18→}
 19→
 20→/// Response from fetching a template.
 21→#[derive(Debug)]
 22→pub struct FetchResponse {
 23→    /// The template content.
 24→    pub content: String,
 25→    /// ETag header if present.
 26→    pub etag: Option<String>,
 27→    /// Last-Modified header if present.
 28→    pub last_modified: Option<String>,
 29→}
 30→
 31→impl HttpFetcher {
 32→    /// Create a new HTTP fetcher with default 30-second timeout.
 33→    pub fn new() -> Self {
 34→        Self::with_timeout(Duration::from_secs(30))
 35→    }
 36→
 37→    /// Create a new HTTP fetcher with custom timeout.
 38→    pub fn with_timeout(timeout: Duration) -> Self {
 39→        Self {
 40→            client: Client::builder()
 41→                .user_agent("bivvy")
 42→                .timeout(timeout)
 43→                .build()
 44→                .expect("Failed to build HTTP client"),
 45→            timeout,
 46→            max_response_size: DEFAULT_MAX_RESPONSE_SIZE,
 47→        }
 48→    }
 49→
 50→    /// Create a new HTTP fetcher with custom timeout and max response size.
 51→    #[cfg(test)]
 52→    pub fn with_max_size(timeout: Duration, max_response_size: u64) -> Self {
 53→        Self {
 54→            client: Client::builder()
 55→                .user_agent("bivvy")
 56→                .timeout(timeout)
 57→                .build()
 58→                .expect("Failed to build HTTP client"),
 59→            timeout,
 60→            max_response_size,
 61→        }
 62→    }
 63→
 64→    /// Get the configured timeout.
 65→    pub fn timeout(&self) -> Duration {
 66→        self.timeout
 67→    }
 68→
 69→    /// Fetch a template from a URL.
 70→    pub fn fetch(&self, url: &str) -> Result<FetchResponse> {
 71→        let response = self.client.get(url).send()?;
 72→
 73→        if !response.status().is_success() {
 74→            bail!("HTTP {} fetching {}", response.status(), url);
 75→        }
 76→
 77→        // Check Content-Length if available
 78→        if let Some(len) = response.content_length() {
 79→            if len > self.max_response_size {
 80→                bail!(
 81→                    "Response too large ({} bytes, max {} bytes) from {}",
 82→                    len,
 83→                    self.max_response_size,
 84→                    url
 85→                );
 86→            }
 87→        }
 88→
 89→        let etag = response
 90→            .headers()
 91→            .get("etag")
 92→            .and_then(|v| v.to_str().ok())
 93→            .map(String::from);
 94→
 95→        let last_modified = response
 96→            .headers()
 97→            .get("last-modified")
 98→            .and_then(|v| v.to_str().ok())
 99→            .map(String::from);
100→
101→        let content = response.text()?;
102→
103→        // Also check actual content size (in case Content-Length was missing/wrong)
104→        if content.len() as u64 > self.max_response_size {
105→            bail!(
106→                "Response too large ({} bytes, max {} bytes) from {}",
107→                content.len(),
108→                self.max_response_size,
109→                url
110→            );
111→        }
112→
113→        Ok(FetchResponse {
114→            content,
115→            etag,
116→            last_modified,
117→        })
118→    }
119→
120→    /// Fetch with conditional request (If-None-Match).
121→    ///
122→    /// Returns `None` if content unchanged (304 Not Modified).
123→    pub fn fetch_if_changed(&self, url: &str, etag: Option<&str>) -> Result<Option<FetchResponse>> {
124→        let mut request = self.client.get(url);
125→
126→        if let Some(etag) = etag {
127→            request = request.header("If-None-Match", etag);
128→        }
129→
130→        let response = request.send()?;
131→
132→        if response.status() == reqwest::StatusCode::NOT_MODIFIED {
133→            return Ok(None);
134→        }
135→
136→        if !response.status().is_success() {
137→            bail!("HTTP {} fetching {}", response.status(), url);
138→        }
139→
140→        // Check Content-Length if available
141→        if let Some(len) = response.content_length() {
142→            if len > self.max_response_size {
143→                bail!(
144→                    "Response too large ({} bytes, max {} bytes) from {}",
145→                    len,
146→                    self.max_response_size,
147→                    url
148→                );
149→            }
150→        }

  1→//! Cache command implementation.
  2→//!
  3→//! Provides `bivvy cache list`, `bivvy cache clear`, etc.
  4→
  5→use anyhow::Result;
  6→use clap::{Args, Subcommand};
  7→
  8→use crate::cache::{default_cache_dir, format_duration, CacheStore, CacheValidator};
  9→use crate::ui::{Prompt, PromptResult, PromptType, UserInterface};
 10→
 11→use super::dispatcher::{Command, CommandResult};
 12→
 13→/// Arguments for the cache command.
 14→#[derive(Debug, Clone, Args)]
 15→pub struct CacheArgs {
 16→    #[command(subcommand)]
 17→    pub command: CacheSubcommand,
 18→}
 19→
 20→/// Cache subcommands.
 21→#[derive(Debug, Clone, Subcommand)]
 22→pub enum CacheSubcommand {
 23→    /// List cached entries.
 24→    List {
 25→        /// Show detailed information.
 26→        #[arg(long)]
 27→        verbose: bool,
 28→        /// Output as JSON.
 29→        #[arg(long)]
 30→        json: bool,
 31→    },
 32→    /// Clear the cache.
 33→    Clear {
 34→        /// Only clear expired entries.
 35→        #[arg(long)]
 36→        expired: bool,
 37→        /// Don't prompt for confirmation.
 38→        #[arg(short, long)]
 39→        force: bool,
 40→    },
 41→    /// Show cache statistics.
 42→    Stats,
 43→}
 44→
 45→/// The cache command implementation.
 46→pub struct CacheCommand {
 47→    args: CacheArgs,
 48→}
 49→
 50→impl CacheCommand {
 51→    /// Create a new cache command.
 52→    pub fn new(args: CacheArgs) -> Self {
 53→        Self { args }
 54→    }
 55→}
 56→
 57→impl Command for CacheCommand {
 58→    fn execute(&self, ui: &mut dyn UserInterface) -> crate::error::Result<CommandResult> {
 59→        let cache_dir = default_cache_dir();
 60→        let store = CacheStore::new(&cache_dir);
 61→
 62→        let exit_code = match &self.args.command {
 63→            CacheSubcommand::List { verbose, json } => list_cache(&store, *verbose, *json, ui)?,
 64→            CacheSubcommand::Clear { expired, force } => clear_cache(&store, *expired, *force, ui)?,
 65→            CacheSubcommand::Stats => show_stats(&store, ui)?,
 66→        };
 67→
 68→        Ok(if exit_code == 0 {
 69→            CommandResult::success()
 70→        } else {
 71→            CommandResult::failure(exit_code)
 72→        })
 73→    }
 74→}
 75→
 76→fn list_cache(
 77→    store: &CacheStore,
 78→    verbose: bool,
 79→    json: bool,
 80→    ui: &mut dyn UserInterface,
 81→) -> Result<i32> {
 82→    let entries = store.list()?;
 83→
 84→    if entries.is_empty() {
 85→        ui.message("Cache is empty");
 86→        return Ok(0);
 87→    }
 88→
 89→    if json {
 90→        let output = serde_json::to_string_pretty(&entries)?;
 91→        ui.message(&output);
 92→        return Ok(0);
 93→    }
 94→
 95→    ui.message(&format!("{} cached entries:\n", entries.len()));
 96→
 97→    for entry in entries {
 98→        let status = if entry.is_expired() {
 99→            "expired"
100→        } else {
101→            "fresh"
102→        };
103→        let remaining = entry.metadata.remaining_ttl();
104→        let ttl_str = if remaining > 0 {
105→            format_duration(chrono::Duration::seconds(remaining))
106→        } else {
107→            "expired".to_string()
108→        };
109→
110→        if verbose {
111→            ui.message(&format!("  {} ({})", entry.template_name, entry.source_id));
112→            ui.message(&format!("    Status: {}", status));
113→            ui.message(&format!("    TTL: {}", ttl_str));
114→            ui.message(&format!("    Size: {} bytes", entry.metadata.size_bytes));
115→            if let Some(etag) = &entry.metadata.etag {
116→                ui.message(&format!("    ETag: {}", etag));
117→            }
118→            if let Some(sha) = &entry.metadata.commit_sha {
119→                ui.message(&format!("    Commit: {}", sha));
120→            }
121→            ui.message("");
122→        } else {
123→            ui.message(&format!(
124→                "  {} [{}] {}",
125→                entry.template_name, status, ttl_str
126→            ));
127→        }
128→    }
129→
130→    Ok(0)
131→}
132→
133→fn clear_cache(
134→    store: &CacheStore,
135→    expired_only: bool,
136→    force: bool,
137→    ui: &mut dyn UserInterface,
138→) -> Result<i32> {
139→    if expired_only {
140→        let validator = CacheValidator::new(store);
141→        let removed = validator.cleanup_expired()?;
142→        ui.success(&format!("Cleared {} expired entries", removed));
143→        return Ok(0);
144→    }
145→
146→    let entries = store.list()?;
147→    if entries.is_empty() {
148→        ui.message("Cache is already empty");
149→        return Ok(0);
150→    }
151→
152→    let count = entries.len();
153→    if !force && ui.is_interactive() {
154→        let prompt = Prompt {
155→            key: "clear_cache".to_string(),
156→            question: format!("Clear {} cached entries?", count),
157→            prompt_type: PromptType::Confirm,
158→            default: Some("false".to_string()),
159→        };
160→
161→        match ui.prompt(&prompt)? {
162→            PromptResult::Bool(true) => {}
163→            _ => {
164→                ui.message("Cancelled");
165→                return Ok(0);
166→            }
167→        }
168→    }
169→
170→    let cleared = store.clear()?;
171→    ui.success(&format!("Cleared {} entries", cleared));
172→
173→    Ok(0)
174→}
175→
176→fn show_stats(store: &CacheStore, ui: &mut dyn UserInterface) -> Result<i32> {
177→    let entries = store.list()?;
178→    let total_size = store.total_size()?;
179→    let expired_count = entries.iter().filter(|e| e.is_expired()).count();
180→    let fresh_count = entries.len() - expired_count;
181→
182→    ui.message("Cache Statistics:\n");
183→    ui.message(&format!("  Total entries: {}", entries.len()));
184→    ui.message(&format!("  Fresh: {}", fresh_count));
185→    ui.message(&format!("  Expired: {}", expired_count));
186→    ui.message(&format!("  Total size: {} bytes", total_size));
187→    ui.message(&format!("  Location: {}", store.root().display()));
188→
189→    Ok(0)
190→}
