  1→//! Cache storage implementation.
  2→
  3→use anyhow::{Context, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→use std::sync::atomic::{AtomicU64, Ordering};
  8→
  9→use super::entry::CacheEntry;
 10→
 11→/// Counter for generating unique temp file names across threads.
 12→static TEMP_COUNTER: AtomicU64 = AtomicU64::new(0);
 13→
 14→/// Write content to a temporary file then atomically rename it into place.
 15→///
 16→/// This prevents readers from observing partially-written files when
 17→/// multiple threads or processes write to the same cache path.
 18→fn atomic_write(path: &Path, content: impl AsRef<[u8]>) -> Result<()> {
 19→    let id = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
 20→    let file_name = path.file_name().unwrap_or_default().to_string_lossy();
 21→    let temp_path = path.with_file_name(format!("{file_name}.tmp.{id}"));
 22→
 23→    fs::write(&temp_path, content.as_ref())
 24→        .with_context(|| format!("Failed to write cache temp file {:?}", temp_path))?;
 25→
 26→    if let Err(e) = fs::rename(&temp_path, path) {
 27→        let _ = fs::remove_file(&temp_path);
 28→        return Err(e).with_context(|| format!("Failed to rename cache temp file to {:?}", path));
 29→    }
 30→
 31→    Ok(())
 32→}
 33→
 34→/// Storage for cached templates.
 35→pub struct CacheStore {
 36→    /// Root directory for cache.
 37→    root: PathBuf,
 38→}
 39→
 40→impl CacheStore {
 41→    /// Create a new cache store.
 42→    pub fn new(root: impl Into<PathBuf>) -> Self {
 43→        Self { root: root.into() }
 44→    }
 45→
 46→    /// Get the cache root directory.
 47→    pub fn root(&self) -> &Path {
 48→        &self.root
 49→    }
 50→
 51→    /// Ensure the cache directory exists.
 52→    fn ensure_dir(&self) -> Result<()> {
 53→        fs::create_dir_all(&self.root)
 54→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 55→    }
 56→
 57→    /// Get the path for storing an entry's content.
 58→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 59→        let key = format!("{}:{}", source_id, template_name);
 60→        let hash = Sha256::digest(key.as_bytes());
 61→        let hash_str = hex::encode(&hash[..16]);
 62→        self.root.join(hash_str)
 63→    }
 64→
 65→    /// Get the metadata file path for an entry.
 66→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 67→        self.content_path(source_id, template_name)
 68→            .with_extension("meta.json")
 69→    }
 70→
 71→    /// Store content and return a cache entry.
 72→    pub fn store(
 73→        &self,
 74→        source_id: &str,
 75→        template_name: &str,
 76→        content: &str,
 77→        ttl_seconds: u64,
 78→    ) -> Result<CacheEntry> {
 79→        self.ensure_dir()?;
 80→
 81→        let content_path = self.content_path(source_id, template_name);
 82→        atomic_write(&content_path, content)?;
 83→
 84→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 85→            .with_size(content.len() as u64);
 86→
 87→        self.save_metadata(&entry)?;
 88→
 89→        Ok(entry)
 90→    }
 91→
 92→    /// Load a cached entry's metadata.
 93→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 94→        let meta_path = self.metadata_path(source_id, template_name);
 95→
 96→        if !meta_path.exists() {
 97→            return Ok(None);
 98→        }
 99→
100→        let json = fs::read_to_string(&meta_path)?;
101→        let entry: CacheEntry = serde_json::from_str(&json)?;
102→
103→        Ok(Some(entry))
104→    }
105→
106→    /// Read the cached content.
107→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
108→        fs::read_to_string(&entry.content_path).with_context(|| {
109→            format!(
110→                "Failed to read cached content from {:?}",
111→                entry.content_path
112→            )
113→        })
114→    }
115→
116→    /// Save entry metadata.
117→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
118→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
119→        let json = serde_json::to_string_pretty(entry)?;
120→        atomic_write(&meta_path, json)?;
121→        Ok(())
122→    }
123→
124→    /// Update an entry's metadata (e.g., after revalidation).
125→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
126→        self.save_metadata(entry)
127→    }
128→
129→    /// Remove a cached entry.
130→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
131→        let content_path = self.content_path(source_id, template_name);
132→        let meta_path = self.metadata_path(source_id, template_name);
133→
134→        let mut removed = false;
135→
136→        if content_path.exists() {
137→            fs::remove_file(&content_path)?;
138→            removed = true;
139→        }
140→
141→        if meta_path.exists() {
142→            fs::remove_file(&meta_path)?;
143→            removed = true;
144→        }
145→
146→        Ok(removed)
147→    }
148→
149→    /// List all cached entries.
150→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
151→        self.ensure_dir()?;
152→
153→        let mut entries = Vec::new();
154→
155→        for entry in fs::read_dir(&self.root)? {
156→            let entry = entry?;
157→            let path = entry.path();
158→
159→            if path.extension().is_some_and(|e| e == "json") {
160→                if let Ok(json) = fs::read_to_string(&path) {
161→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
162→                        entries.push(cache_entry);
163→                    }
164→                }
165→            }
166→        }
167→
168→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
169→        Ok(entries)
170→    }
171→
172→    /// Clear all cached entries.
173→    pub fn clear(&self) -> Result<usize> {
174→        let entries = self.list()?;
175→        let count = entries.len();
176→
177→        for entry in entries {
178→            let _ = self.remove(&entry.source_id, &entry.template_name);
179→        }
180→
181→        Ok(count)
182→    }
183→
184→    /// Get total cache size in bytes.
185→    pub fn total_size(&self) -> Result<u64> {
186→        let entries = self.list()?;
187→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
188→    }
189→}
